/*** ComDAO.getFacInfo 공장 가져올때 사용 ***/ select fac_cd as fac_cd , fac_nm as fac_nm from bcc300 where 1 = 1
and fac_cd = #{facCd}
and fac_nm LIKE '%' + #{facNm} + '%'

/*** ComDAO.getWhInfo 창고 가져올때 사용 ***/ select wh_cd as 'whCd', wh_nm as 'whNm' from bcw100 where 1 = 1
and fac_cd = #{facCd}
and fac_nm LIKE '%' + #{facNm} + '%'
and wh_nm LIKE '%' + #{whNm} + '%'
